import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import re
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

# Configuration
BASE_DIR = '/srv/shared/documents'
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.docx', '.xlsx', '.png', '.jpg'}
MAX_PATH_LENGTH = 255
API_KEYS = {}  # populated from secure store at startup


def constant_time_compare(a, b):
    """Timing-safe comparison for authentication tokens."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        # Validate against stored API keys
        user_id = request.headers.get('X-User-ID', '')
        if not user_id or user_id not in API_KEYS:
            abort(401)
        if not constant_time_compare(token, API_KEYS[user_id]):
            abort(403)
        return f(*args, **kwargs)
    return decorated


def normalize_path_component(component):
    """Normalize a path component to canonical form for consistent security checks.
    Uses NFC normalization to prevent homoglyph/encoding attacks.
    """
    # Strip null bytes
    component = component.replace('\x00', '')
    # Normalize Unicode to NFC form for consistent comparison
    normalized = unicodedata.normalize('NFC', component)
    return normalized


def is_path_safe(user_path):
    """Validate that the requested path doesn't escape the base directory.
    Performs Unicode normalization to prevent encoding-based bypasses.
    """
    if not user_path:
        return False

    if len(user_path) > MAX_PATH_LENGTH:
        return False

    # Reject obvious traversal attempts
    if '\x00' in user_path:
        return False

    # Normalize each component for consistent security checking
    parts = user_path.split('/')
    normalized_parts = []
    for part in parts:
        normalized = normalize_path_component(part)
        # Check for traversal after normalization
        if normalized == '..' or normalized == '.':
            return False
        # Check for hidden files
        if normalized.startswith('.'):
            return False
        normalized_parts.append(normalized)

    normalized_path = '/'.join(normalized_parts)

    # Verify the resolved path stays within BASE_DIR
    # Use the NORMALIZED path for the security check
    full_path = os.path.normpath(os.path.join(BASE_DIR, normalized_path))
    if not full_path.startswith(os.path.normpath(BASE_DIR) + os.sep):
        return False

    # Verify extension is allowed
    _, ext = os.path.splitext(normalized_path)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return False

    return True


def resolve_file_path(user_path):
    """Resolve the actual filesystem path for the requested file.
    Returns the path to serve to the user.
    """
    # Use the ORIGINAL path (not normalized) for filesystem access
    # This preserves the actual filename on disk
    parts = user_path.split('/')
    clean_parts = [p.replace('\x00', '') for p in parts if p]
    resolved = os.path.join(BASE_DIR, *clean_parts)
    return os.path.normpath(resolved)


@app.route('/api/files/<path:filepath>', methods=['GET'])
@require_auth
def get_file(filepath):
    """Serve a file from the shared documents directory."""
    # Security validation
    if not is_path_safe(filepath):
        abort(403)

    # Resolve actual path
    actual_path = resolve_file_path(filepath)

    if not os.path.isfile(actual_path):
        abort(404)

    return send_file(actual_path)


@app.route('/api/files/<path:filepath>', methods=['DELETE'])
@require_auth
def delete_file(filepath):
    """Delete a file from the shared documents directory."""
    if not is_path_safe(filepath):
        abort(403)

    actual_path = resolve_file_path(filepath)

    if not os.path.isfile(actual_path):
        abort(404)

    os.remove(actual_path)
    return jsonify({'status': 'deleted', 'path': filepath})


@app.route('/api/list/<path:dirpath>', methods=['GET'])
@require_auth  
def list_directory(dirpath):
    """List files in a subdirectory."""
    if not dirpath:
        dirpath = ''

    parts = dirpath.split('/')
    normalized_parts = [normalize_path_component(p) for p in parts if p]

    for part in normalized_parts:
        if part == '..' or part == '.' or part.startswith('.'):
            abort(403)

    full_dir = os.path.normpath(os.path.join(BASE_DIR, *normalized_parts))
    if not full_dir.startswith(os.path.normpath(BASE_DIR)):
        abort(403)

    if not os.path.isdir(full_dir):
        abort(404)

    files = []
    for entry in os.scandir(full_dir):
        if entry.is_file() and not entry.name.startswith('.'):
            _, ext = os.path.splitext(entry.name)
            if ext.lower() in ALLOWED_EXTENSIONS:
                files.append({
                    'name': entry.name,
                    'size': entry.stat().st_size
                })

    return jsonify({'files': files, 'directory': dirpath})


def init_api_keys():
    """Load API keys from environment (in production, use a secrets manager)."""
    keys_raw = os.environ.get('API_KEYS', '')
    for entry in keys_raw.split(';'):
        if '=' in entry:
            uid, key = entry.split('=', 1)
            API_KEYS[uid.strip()] = key.strip()


if __name__ == '__main__':
    init_api_keys()
    app.run(host='127.0.0.1', port=8443, ssl_context='adhoc')
